      )
      .then((rows) => rows[0] ?? null);
    if (!existing) throw notFound("Join request not found");
    if (existing.status !== "pending_approval")
      throw conflict("Join request is not pending");

    const invite = await db
      .select()
      .from(invites)
      .where(eq(invites.id, existing.inviteId))
      .then((rows) => rows[0] ?? null);
    if (!invite) throw notFound("Invite not found");

    let createdAgentId: string | null = existing.createdAgentId ?? null;
    if (existing.requestType === "human") {
      if (!existing.requestingUserId)
        throw conflict("Join request missing user identity");
      const membershipRole = resolveHumanInviteRole(
        invite.defaultsPayload as Record<string, unknown> | null,
      );
      await access.ensureMembership(
        companyId, "user", existing.requestingUserId, membershipRole, "active"
      );
      const grants = humanJoinGrantsFromDefaults(
        invite.defaultsPayload as Record<string, unknown> | null,
        membershipRole
      );
      await access.setPrincipalGrants(
        companyId, "user", existing.requestingUserId, grants, req.actor.userId ?? null
      );
    } else {
      const existingAgents = await agents.list(companyId);
      const managerId = resolveJoinRequestAgentManagerId(existingAgents);
      if (!managerId) {
        throw conflict(
          "Join request cannot be approved because this company has no active CEO"
        );
      }

      const agentName = deduplicateAgentName(
        existing.agentName ?? "New Agent",
        existingAgents.map((a) => ({ id: a.id, name: a.name, status: a.status }))
      );

      const created = await agents.create(companyId, {
        name: agentName,
        role: "general",
        title: null,
        status: "idle",
        reportsTo: managerId,
        capabilities: existing.capabilities ?? null,
        adapterType: existing.adapterType ?? "process",
        adapterConfig:
          existing.agentDefaultsPayload &&
          typeof existing.agentDefaultsPayload === "object"
            ? (existing.agentDefaultsPayload as Record<string, unknown>)
            : {},
        runtimeConfig: {},
        budgetMonthlyCents: 0,
        spentMonthlyCents: 0,
        permissions: {},
        lastHeartbeatAt: null,
        metadata: null
      });
      createdAgentId = created.id;
      await access.ensureMembership(companyId, "agent", created.id, "member", "active");
      const grants = agentJoinGrantsFromDefaults(
        invite.defaultsPayload as Record<string, unknown> | null
      );
      await access.setPrincipalGrants(
        companyId, "agent", created.id, grants, req.actor.userId ?? null
      );
    }

    const approved = await db
      .update(joinRequests)
      .set({
        status: "approved",
        approvedByUserId:
          req.actor.userId ?? (isLocalImplicit(req) ? "local-board" : null),
        approvedAt: new Date(),
        createdAgentId,
        updatedAt: new Date()
      })
      .where(eq(joinRequests.id, requestId))
      .returning()
      .then((rows) => rows[0]);

    await logActivity(db, {
      companyId,
      actorType: "user",
      actorId: req.actor.userId ?? "board",
      action: "join.approved",
      entityType: "join_request",
      entityId: requestId,
      details: { requestType: existing.requestType, createdAgentId }
    });

    if (createdAgentId) {
      void notifyHireApproved(db, {
        companyId,
        agentId: createdAgentId,
        source: "join_request",
        sourceId: requestId,
        approvedAt: new Date()
      }).catch(() => {});
    }

    res.json(toJoinRequestResponse(approved));
  }
);
